package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.AppealResolution;import com.easyperformance.program.ProgramTypes.FeedbackStatus;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="program_feedback",uniqueConstraints=@UniqueConstraint(name="uq_program_feedback_participant",columnNames={"tenant_id","participant_id"}),indexes=@Index(name="ix_program_feedback_tenant_status",columnList="tenant_id, program_id, status"))
public class ProgramFeedback extends TenantAwareAuditEntity{
 @Id@Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="program_id",columnDefinition="uuid",nullable=false)private UUID programId;@Column(name="participant_id",columnDefinition="uuid",nullable=false)private UUID participantId;@Column(name="writer_employee_id",columnDefinition="uuid",nullable=false)private UUID writerEmployeeId;@Column(columnDefinition="text")private String comment;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private FeedbackStatus status;@Column(name="appeal_reason",columnDefinition="text")private String appealReason;@Enumerated(EnumType.STRING)@Column(length=20)private AppealResolution resolution;@Column(name="resolution_comment",columnDefinition="text")private String resolutionComment;@Column(name="delivered_at")private Instant deliveredAt;@Column(name="resolved_at")private Instant resolvedAt;@Version@Column(name="row_version",nullable=false)private long rowVersion;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();if(status==null)status=FeedbackStatus.DRAFT;}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getProgramId(){return programId;}public void setProgramId(UUID v){programId=v;}public UUID getParticipantId(){return participantId;}public void setParticipantId(UUID v){participantId=v;}public UUID getWriterEmployeeId(){return writerEmployeeId;}public void setWriterEmployeeId(UUID v){writerEmployeeId=v;}public String getComment(){return comment;}public void setComment(String v){comment=v;}public FeedbackStatus getStatus(){return status;}public void setStatus(FeedbackStatus v){status=v;}public String getAppealReason(){return appealReason;}public void setAppealReason(String v){appealReason=v;}public AppealResolution getResolution(){return resolution;}public void setResolution(AppealResolution v){resolution=v;}public String getResolutionComment(){return resolutionComment;}public void setResolutionComment(String v){resolutionComment=v;}public Instant getDeliveredAt(){return deliveredAt;}public void setDeliveredAt(Instant v){deliveredAt=v;}public Instant getResolvedAt(){return resolvedAt;}public void setResolvedAt(Instant v){resolvedAt=v;}public long getRowVersion(){return rowVersion;}
}
